```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_route53_zone" "primary" {
  name = "primary"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name = "aws_route53_example_com"
}

resource "aws_iam_role" "route53_query_logging_role" {
  name = "route53_query_logging_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "route53.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "route53_query_logging_role_cloudwatch" {
  role       = aws_iam_role.route53_query_logging_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

resource "aws_iam_role_policy" "route53_query_logging_policy" {
  name   = "route53_query_logging_policy"
  role   = aws_iam_role.route53_query_logging_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = aws_cloudwatch_log_group.aws_route53_example_com.arn
    }]
  })
}

resource "aws_route53_resolver_query_log_config" "route53_query_log_config" {
  name             = "route53_query_log_config"
  destination_arn  = aws_cloudwatch_log_group.aws_route53_example_com.arn
  depends_on       = [
    aws_route53_zone.primary,
    aws_cloudwatch_log_group.aws_route53_example_com,
    aws_iam_role_policy.route53_query_logging_policy
  ]
}
```

