resource "aws_elasticbeanstalk_environment" "blue_environment" {
  name                = "blue"
  application         = "my-application"
  environment_name    = "blue-environment"
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.6 running Python 3.10"
  description         = "Blue environment for Blue/Green deployment"
  tags = {
    Environment = "blue"
  }
}

resource "aws_elasticbeanstalk_environment" "green_environment" {
  name                = "green"
  application         = "my-application"
  environment_name    = "green-environment"
  solution_stack_name = "64bit Amazon Linux 2023 v3.3.6 running Python 3.10"
  description         = "Green environment for Blue/Green deployment"
  tags = {
    Environment = "green"
  }
}

# Assume the Route53 zone ID is known or created elsewhere
variable "route53_zone_id" {
  default = "Z1234567890ABCDEF"
}

# Create Route53 records for blue and green environments
resource "aws_route53_record" "blue_record" {
  name    = "blue.example.com"
  type    = "A"
  zone_id = var.route53_zone_id
  records = [aws_elasticbeanstalk_environment.blue_environment.cname]
  ttl     = 300
  set_identifier = "blue"
}

resource "aws_route53_record" "green_record" {
  name    = "green.example.com"
  type    = "A"
  zone_id = var.route53_zone_id
  records = [aws_elasticbeanstalk_environment.green_environment.cname]
  ttl     = 300
  set_identifier = "green"
}

# Create a weighted Route53 record to manage traffic between blue and green
resource "aws_route53_record" "weighted_record" {
  name    = "example.com"
  type    = "A"
  zone_id = var.route53_zone_id
  ttl     = 300

  weighted_routing_policy {
    weight = 1
  }

  records = [
    aws_route53_record.blue_record.name,
    aws_route53_record.green_record.name
  ]
}
