Here is a complete Terraform HCL program that creates an `aws_lex_bot` with basic configuration. The bot includes a single intent, a clarification prompt, and an abort statement. All required attributes are included, and default values are used where appropriate.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_bot" "lex_bot" {
  name                     = "example-lex-bot"
  child_directed           = false
  description              = "An example Lex bot for demonstration purposes"
  detect_sentiment         = true
  enable_model_improvements = true
  idle_session_ttl_in_seconds = 300
  locale                   = "en-US"
  nlu_intent_confidence_threshold = 0.4
  process_behavior         = "BUILD"
  voice_id                 = "Joanna"

  clarification_prompt {
    max_attempts = 3
    response_card {
      version = "1.0"
      title   = "Clarification Needed"
      content = ["Could you please rephrase that?"]
      buttons = [
        {
          text = "Yes"
          value = "yes"
        },
        {
          text = "No"
          value = "no"
        }
      ]
    }
  }

  abort_statement {
    response_card {
      version = "1.0"
      title   = "Abort"
      content = ["I'm sorry, I can't help with that."]
    }
  }

  intent {
    intent_name    = "GreetingIntent"
    intent_version = "$LATEST"
  }

  timeouts {
    create = "5m"
    delete = "5m"
    update = "5m"
  }
}
```

