resource "aws_kinesis_stream" "input_stream" {
  name             = "flink-input-stream"
  shard_count      = 1
  retention_period = 24
}

resource "aws_iam_role" "flink_role" {
  name = "flink-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "kinesisanalytics.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "flink_role_policy_attachment" {
  role       = aws_iam_role.flink_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonKinesisAnalyticsServiceRole"
}

resource "aws_kinesis_analytics_v2_application" "kinesis_analytics_app" {
  name        = "flink-analytics-app"
  application_code = <<EOF
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.connectors.kinesis.FlinkKinesisConsumer;
import org.apache.flink.streaming.connectors.kinesis.config.ConsumerConfigConstants;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.functions.sink.PrintSinkFunction;

public class FlinkApp {
    public static void main(String[] args) throws Exception {
        final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        FlinkKinesisConsumer<String> consumer = new FlinkKinesisConsumer<>(
            "flink-input-stream",
            "A1B2C3D4E5F67890",
            new SimpleStringSchema(),
            new Properties() {{
                setProperty(ConsumerConfigConstants.AWS_REGION, "us-west-2");
            }}
        );

        DataStream<String> stream = env.addSource(consumer);

        stream.addSink(new PrintSinkFunction<>());

        env.execute("Flink Kinesis Analytics App");
    }
}
EOF

  runtime_environment {
    runtime_mode = "flink-1_16"
  }

  inputs {
    name = "input"
    kinesis_stream {
      stream_arn = aws_kinesis_stream.input_stream.arn
      role_arn   = aws_iam_role.flink_role.arn
    }
  }

  outputs {
    name = "output"
    kinesis_firehose {
      delivery_stream = "flink-output-delivery-stream"
    }
  }

  tags = {
    Environment = "dev"
  }
}
