        "s3:PutObject",
        "s3:GetObject",
        "s3:ListBucket"
      ]
      Resource = [
        "arn:aws:s3:::firehose-backup-bucket",
        "arn:aws:s3:::firehose-backup-bucket/*"
      ]
    }, {
      Effect = "Allow"
      Action = [
        "firehose:PutRecord",
        "firehose:PutRecordBatch"
      ]
      Resource = "arn:aws:firehose:us-west-2:123456789012:deliverystream/firehose_delivery_stream"
    }, {
      Effect = "Allow"
      Action = [
        "iam:PassRole"
      ]
      Resource = aws_iam_role.firehose_role.arn
    }]
  })
}

resource "aws_iam_role_policy_attachment" "firehose_policy" {
  role       = aws_iam_role.firehose_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSFirehoseFullAccess"
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name = "firehose_delivery_stream"

  splunk_configuration {
    hec_endpoint = "https://splunk.example.com:8088"
    hec_token    = "your_splunk_hec_token"
    hec_endpoint_type = "direct"
    buffering_interval = 300
    buffering_size     = 5
    retry_duration     = 30
    s3_backup_mode     = "Enabled"
  }

  # Optional: S3 backup bucket ARN if needed
  # s3_backup_bucket_arn = "arn:aws:s3:::firehose-backup-bucket"
}
