```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a VPC
resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "firehose-opensearch-vpc"
  }
}

# Create a private subnet within the VPC
resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "firehose-opensearch-private-subnet"
  }
}

# Create a security group for OpenSearch
resource "aws_security_group" "opensearch_sg" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "opensearch-sg"
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a security group for Kinesis Firehose
resource "aws_security_group" "firehose_sg" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "firehose-sg"
  }

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create IAM role for OpenSearch
resource "aws_iam_role" "opensearch_iam_role" {
  name = "opensearch-iam-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "opensearchservice.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Create IAM role for Kinesis Firehose
resource "aws_iam_role" "firehose_iam_role" {
  name = "firehose-iam-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "firehose.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach managed policies to the IAM roles
resource "aws_iam_role_policy_attachment" "opensearch_iam_role_attachment" {
  role       = aws_iam_role.opensearch_iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonOpenSearchServiceFullAccess"
}

resource "aws_iam_role_policy_attachment" "firehose_iam_role_attachment" {
  role       = aws_iam_role.firehose_iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonKinesisFirehoseFullAccess"
}

# Create OpenSearch domain
resource "aws_opensearch_domain" "opensearch_domain" {
  domain_name = "firehose-opensearch-domain"

  cluster_config {
    instance_type = "t3.small.search"
    instance_count = 1
  }

  vpc_options {
    security_group_ids = [aws_security_group.opensearch_sg.id]
    subnet_ids         = [aws_subnet.private_subnet.id]
  }

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { "AWS" = "*" }
      Action = "es:*"
      Resource = "arn:aws:es:us-west-2:123456789012:domain/firehose-opensearch-domain/*"
    }]
  })

  tags = {
    Name = "firehose-opensearch-domain"
  }
}

# Create Kinesis Firehose Delivery Stream with OpenSearch destination
resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name = "firehose-to-opensearch"

  opensearch_configuration {
    domain_arn = aws_opensearch_domain.opensearch_domain.arn
    index_name = "firehose-index"
    role_arn   = aws_iam_role.firehose_iam_role.arn
  }

  tags = {
    Name = "firehose-to-opensearch"
  }
}
```

