```hcl
provider "aws" {
  region = "us-west-2"
}

variable "bucket_suffix" {
  description = "Suffix for the S3 bucket names"
  default     = "test"
}

resource "aws_s3_bucket" "cloudgoat_data_bucket" {
  bucket = "cloudgoat-data-bucket-${var.bucket_suffix}"
  acl    = "private"

  # Ownership controls for ObjectWriter access
  grant {
    type       = "Group"
    permissions = ["FULL_CONTROL"]
    uri         = "http://acs.amazonaws.com/groups/s3/AllUsers"
  }

  # Optional: Add versioning or other settings if needed
}

resource "aws_s3_bucket" "web_data_bucket" {
  bucket = "web-data-bucket-${var.bucket_suffix}"
  acl    = "private"
}

resource "aws_s3_bucket_object" "order_data2_csv" {
  bucket       = aws_s3_bucket.web_data_bucket.bucket
  key          = "order_data2.csv"
  source       = "./order_data2.csv"
  acl          = "public-read"
  content_type = "text/csv"
}

resource "aws_s3_bucket_public_access_block" "web_data_bucket_public_access_block" {
  bucket = aws_s3_bucket.web_data_bucket.bucket

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "web_data_bucket_policy" {
  bucket = aws_s3_bucket.web_data_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = "*"
        Action = "s3:PutObject"
        Resource = "arn:aws:s3:::${aws_s3_bucket.web_data_bucket.bucket}/*"
      }
    ]
  })
}
