Here is the Terraform HCL program that triggers the `test_lambda` Lambda function whenever an EC2 image is created, using AWS CloudWatch Events to detect the event and link it to the Lambda function:

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lambda_function" "test_lambda" {
  function_name    = "test_lambda"
  role             = aws_iam_role.lambda_role.arn
  handler          = "index.handler"
  runtime          = "nodejs18.x"
  filename         = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")

  # Optional: Add environment variables or other configurations
  environment {
    variables = {
      ENV = "test"
    }
  }

  # Optional: Add timeouts
  timeouts {
    create = "10m"
    update = "10m"
    delete = "10m"
  }
}

resource "aws_iam_role" "lambda_role" {
  name = "lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_cloudwatch_event_rule" "ec2_image_creation_rule" {
  name                = "ec2-image-creation-rule"
  description         = "Triggers Lambda function on EC2 image creation"
  event_pattern       = jsonencode({
    source = ["aws.ec2"]
    detail_type = ["EC2 Instance State-change Notification"]
    detail = {
      state = ["pending", "running", "shutting-down", "terminated"]
    }
  })
  is_enabled          = true
}

resource "aws_cloudwatch_event_target" "lambda_event_target" {
  rule      = aws_cloudwatch_event_rule.ec2_image_creation_rule.name
  arn       = aws_lambda_function.test_lambda.arn
  target_id = "test_lambda"
}
```

### Summary:
- **aws_lambda_function.test_lambda**: A Lambda function that will be triggered by the CloudWatch Event Rule.
- **aws_iam_role.lambda_role**: An IAM role that grants the Lambda function execution permissions.
- **aws_iam_role_policy_attachment.lambda_basic_execution**: Attaches the basic execution policy to the Lambda role.
- **aws_cloudwatch_event_rule.ec2_image_creation_rule**: A CloudWatch Event Rule that listens for EC2 image creation events.
- **aws_cloudwatch_event_target.lambda_event_target**: Links the CloudWatch Event Rule to the Lambda function.

This configuration ensures that the Lambda function is triggered whenever an EC2 image is created, as per the user's requirement.

