```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_cloudwatch_composite_alarm" "composite_alarm" {
  alarm_name = "composite_alarm"

  alarm_rule = "ALERT(\"my_metric_alarm\")"

  alarm_description = "A composite alarm that triggers when my_metric_alarm is in the alert state."

  actions_enabled = true

  alarm_actions = [
    "arn:aws:sns:us-west-2:123456789012:my-sns-topic"
