```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_elasticache_user" "redis_user" {
  user_id      = "redis_user_123"
  user_name    = "redis_user"
  engine       = "redis"
  access_string = "on ~app~ * +@all"

  authentication_mode {
    type = "password"
  }
}

resource "aws_elasticache_user" "redis_admin" {
  user_id      = "redis_admin_456"
  user_name    = "redis_admin"
  engine       = "redis"
  access_string = "on ~app~ * +@all"

  authentication_mode {
    type = "password"
  }
}
```

### Description:
This Terraform configuration creates two ElastiCache users for Redis authentication: one regular user (`redis_user`) and one admin user (`redis_admin`). Both users are configured with the `redis` engine and a standard access string that grants full access to the Redis cluster. The `authentication_mode` is set to use a password for authentication. The AWS provider is configured to use the `us-west-2` region, which is a valid and commonly used region for AWS resources.

