  region = "us-west-2"
}

resource "aws_elasticache_user_group" "elasticache_user_group" {
  engine        = "redis"
  user_group_id = "my-elasticache-user-group"
}

resource "aws_elasticache_user" "elasticache_user_1" {
  engine         = "redis"
  user_id        = "user1"
  user_name      = "user1"
  access_string  = "on ~* +@all"

  authentication_mode {
    type = "password"
  }

  depends_on = [aws_elasticache_user_group.elasticache_user_group]
}

resource "aws_elasticache_user" "elasticache_user_2" {
  engine         = "redis"
  user_id        = "user2"
  user_name      = "user2"
  access_string  = "on ~* +@all"

  authentication_mode {
    type = "password"
  }

  depends_on = [aws_elasticache_user_group.elasticache_user_group]
}

resource "aws_elasticache_user" "elasticache_user_3" {
  engine         = "redis"
  user_id        = "user3"
  user_name      = "user3"
  access_string  = "on ~* +@all"

  authentication_mode {
    type = "password"
  }

  depends_on = [aws_elasticache_user_group.elasticache_user_group]
}
```

