I will create a Terraform HCL program that provisions an Amazon DAX cluster using the specified node type (`dax.r4.large`) and replication factor of `1`. Since no IAM role is provided, I will create a basic IAM role with the necessary permissions for DAX.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "dax_role" {
  name = "dax-cluster-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Service = "dax.amazonaws.com" }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "dax_role_policy" {
  role       = aws_iam_role.dax_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDAXRole"
}

resource "aws_dax_cluster" "dax_cluster" {
  cluster_name      = "my-dax-cluster"
  node_type         = "dax.r4.large"
  replication_factor = 1
  iam_role_arn      = aws_iam_role.dax_role.arn

  # Optional attributes with default values
  description       = "DAX cluster for application caching"
  maintenance_window = "sun:08:00-sun:16:00"
  subnet_group_name = "default"
  tags = {
    Environment = "dev"
    Purpose     = "caching"
  }

  timeouts {
    create = "15m"
    delete = "15m"
    update = "15m"
  }
}
```

