provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "msk_logs" {
  bucket = "msk-logs-bucket-12345"
  acl    = "private"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::msk-logs-bucket-12345",
          "arn:aws:s3:::msk-logs-bucket-12345/*"
        ]
        Condition = {
          StringLike = {
            "s3:prefix" = "kafka-logs/"
          }
        }
      }
    ]
  })
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster-12345"
  kafka_version          = "3.3"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets   = ["us-east-1a", "us-east-1b", "us-east-1c"]
    instance_type    = "kafka.m5.large"
    security_groups  = ["sg-12345678"]
    az_distribution  = "balanced"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs_enabled = false
      firehose_enabled        = false
      s3_enabled              = true
      s3_bucket               = aws_s3_bucket.msk_logs.bucket
      s3_prefix               = "kafka-logs/"
    }
  }

  encryption_info {
    encryption_in_transit {
      in_cluster = true
      client_broker = "TLS"
    }
  }

  tags = {
    Environment = "dev"
    Project     = "msk-demo"
  }
}
