}

resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "msk-cluster-logs"
}

resource "aws_s3_bucket" "msk_s3_bucket" {
  bucket = "msk-cluster-logs-bucket"
  tags = {
    Name = "msk-cluster-logs-bucket"
  }
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_stream" {
  name        = "msk-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    bucket_arn   = aws_s3_bucket.msk_s3_bucket.arn
    role_arn     = aws_iam_role.msk_role.arn
    buffering_interval = 300
    buffering_size     = 5
    compression_format = "GZIP"
    prefix             = "msk-logs/"
  }
}

resource "aws_s3_bucket_object" "debezium_plugin" {
  bucket = aws_s3_bucket.msk_s3_bucket.bucket
  key    = "debezium.zip"
  source = "debezium.zip"
}

resource "aws_mskconnect_custom_plugin" "mskconnect_custom_plugin" {
  name        = "debezium-plugin"
  content_type = "ZIP"
  location {
    s3 {
      bucket = aws_s3_bucket.msk_s3_bucket.bucket
      key    = aws_s3_bucket_object.debezium_plugin.key
    }
  }
}

resource "aws_mskconnect_connector" "mskconnect_connector" {
  name                     = "debezium-connector"
  kafkaconnect_version     = "2.6.2"
  service_execution_role_arn = aws_iam_role.msk_role.arn
  connector_configuration = {
    "connector.class" = "io.debezium.connector.mysql.MySqlConnector"
    "database.hostname" = "mysql-host"
    "database.port"     = "3306"
    "database.user"     = "debezium"
    "database.password" = "dbz_password"
    "database.server.id" = "184054"
    "database.server.name" = "inventory-server"
    "database.allowPublicKeyRetrieval" = "true"
    "database.connect.timeout.ms" = "30000"
    "database.socket.timeout.ms" = "30000"
    "database.user" = "debezium"
    "database.password" = "dbz_password"
    "database.include.list" = "inventory"
    "table.include.list" = "inventory.customers"
    "database.server.time_zone" = "UTC"
    "database.time_zone" = "UTC"
    "snapshot.mode" = "when_needed"
    "database.allowPublicKeyRetrieval" = "true"
    "database.ssl.mode" = "none"
  }

  plugin {
    plugin_arn = aws_mskconnect_custom_plugin.mskconnect_custom_plugin.arn
  }

  kafka_cluster {
    bootstrap_servers = aws_msk_cluster.msk_cluster.bootstrap_brokers
  }
}
