```hcl
provider "aws" {
  region = "us-west-2"
}

# Create an IAM role for DAX
resource "aws_iam_role" "dax_role" {
  name = "dax-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "dax.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

# Attach the necessary policy to the IAM role
resource "aws_iam_role_policy_attachment" "dax_role_policy" {
  role       = aws_iam_role.dax_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonDAXFullAccess"
}

# Create a DAX cluster
resource "aws_dax_cluster" "dax_cluster" {
  cluster_name           = "my-dax-cluster"
  iam_role_arn           = aws_iam_role.dax_role.arn
  node_type              = "dax.r4.large"
  replication_factor     = 3
  availability_zones     = ["us-west-2a", "us-west-2b", "us-west-2c"]
  maintenance_window     = "sun:08:00-sun:16:00"
  description            = "My DAX cluster for caching"
  subnet_group_name      = "default"
  security_group_ids     = [aws_security_group.dax_sg.id]
  tags = {
    Environment = "production"
  }

  timeouts {
    create = "30m"
    delete = "30m"
    update = "30m"
  }

  server_side_encryption {
    enabled = true
  }
}

# Create a security group for DAX
