provider "aws" {
  region = "us-east-1"
}

resource "aws_kms_key" "voice_connector_key" {
  description             = "KMS key for encrypting Chime Voice Connectors"
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.voice_connector_key_policy.json
}

data "aws_iam_policy_document" "voice_connector_key_policy" {
  statement {
    effect = "Allow"

    principals {
      type = "Service"
      identifiers = ["chime.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]

    resources = ["*"]
  }
}

