  }
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = false
  tags = {
    Name = "autograder_subnet"
  }
}

resource "aws_security_group" "autograder_security_group" {
  vpc_id = aws_vpc.autograder_vpc.id
  name   = "autograder_security_group"
  description = "Security group for autograder CodeBuild project to restrict internet access."

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "autograder_security_group"
  }
}

resource "aws_s3_bucket" "autograder_code_storage" {
  bucket = "autograder-code-storage-12345"
  tags = {
    Name = "autograder_code_storage"
  }

  # Allow CodeBuild to access the bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = [
          "arn:aws:s3:::autograder-code-storage-12345/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role" "codebuild_role" {
  name = "autograder_codebuild_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_s3_access" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_codebuild_project" "autograder_codebuild" {
  name          = "autograder_codebuild"
  description   = "CodeBuild project for running student code in an isolated environment."
  service_role  = aws_iam_role.codebuild_role.arn

  source {
    type      = "CODEPIPELINE"
    location  = "https://github.com/yourorg/autograder-code"
  }

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    type                = "LINUX_CONTAINER"
    image               = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    compute_type        = "BUILD_GENERAL1_SMALL"
  }

  vpc_config {
