LLM Output #0:
Here is the Terraform HCL program that fulfills the requirement of running a piece of code every day at 7 UTC using AWS EventBridge and AWS Lambda:

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "code_executor_lambda" {
  function_name    = "code_executor_lambda"
  role             = aws_iam_role.lambda_execution_role.arn
  handler          = "lambda_function.handler"
  runtime          = "python3.9"
  filename         = "lambda_function.zip"
  source_code_hash = filebase64sha256("lambda_function.zip")

  # Optional: Add more configurations if needed
  memory_size      = 128
  timeout          = 30
}

resource "aws_eventbridge_rule" "daily_code_execution_rule" {
  name        = "daily_code_execution_rule"
  description = "Trigger Lambda function daily at 7 UTC"
  schedule_expression = "rate(1 day)"
}

resource "aws_eventbridge_rule_target" "eventbridge_lambda_target" {
  rule      = aws_eventbridge_rule.daily_code_execution_rule.name
  target_id = "code_executor_lambda"
  arn       = aws_lambda_function.code_executor_lambda.arn
}
```

### Description:
This Terraform configuration sets up the following infrastructure:

1. **AWS IAM Role (`lambda_execution_role`)**: An IAM role that allows the Lambda function to execute and is assumed by AWS Lambda.
2. **IAM Role Policy Attachment (`lambda_basic_execution`)**: Attaches the AWSLambdaBasicExecutionRole policy to the IAM role, granting basic execution permissions.
3. **AWS Lambda Function (`code_executor_lambda`)**: A Lambda function that will be triggered by the EventBridge rule. It assumes the IAM role and is configured with a placeholder for the handler and runtime (Python 3.9).
4. **AWS EventBridge Rule (`daily_code_execution_rule`)**: A rule that triggers the Lambda function every day at 7 UTC using the `rate(1 day)` schedule.
5. **EventBridge Rule Target (`eventbridge_lambda_target`)**: Links the EventBridge rule to the Lambda function as a target.

This configuration ensures that the code runs daily at 7 UTC as required. You can replace the `filename` and `handler` with your actual Lambda code and handler function.

