provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-12345"
  acl    = "private"

  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  versioning {
    enabled = false
  }

  lifecycle_rule {
    enabled = true
    id      = "delete-old-objects"
    prefix  = "videos/"
    expiration {
      days = 30
    }
  }
}

resource "aws_s3_bucket_policy" "video_content_bucket_policy" {
  bucket = aws_s3_bucket.video_content_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = "s3:GetObject"
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_content_bucket.bucket}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = "arn:aws:cloudfront::${aws_caller_identity.id}:distribution/${aws_cloudfront_distribution.video_streaming_distribution.id}"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "cloudfront_iam_role" {
  name = "cloudfront-iam-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudfront_iam_role_attachment" {
  role       = aws_iam_role.cloudfront_iam_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  enabled             = true
  comment             = "CloudFront distribution for video streaming site"
  default_root_object = "index.html"

  origin {
    domain_name = aws_s3_bucket.video_content_bucket.bucket_domain_name
    origin_id   = "S3-Origin-${aws_s3_bucket.video_content_bucket.bucket}"

    origin_path = "/videos"
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = aws_cloudfront_distribution.video_streaming_distribution.origin[0].origin_id
    viewer_protocol_policy = "allow-all"
    compress = true
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}
