provider "aws" {
  region = "us-west-2"
}

resource "aws_security_group" "lb_security_group" {
  name        = "lb_security_group"
  description = "Allow incoming HTTP traffic and outgoing traffic to backend servers"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lb_security_group"
  }
}

