    Name = "postgres_kms_key"
  }
}

resource "aws_db_parameter_group" "postgres_parameter_group" {
  family = "postgres14"
  name   = "postgres_parameter_group"
  tags = {
    Name = "postgres_parameter_group"
  }

  parameter {
    name  = "log_statement"
    value = "all"
    apply_method = "pending-reboot"
  }

  parameter {
    name  = "max_connections"
    value = "100"
    apply_method = "pending-reboot"
  }
}

resource "aws_db_security_group" "postgres_security_group" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "postgres_security_group"
  tags = {
    Name = "postgres_security_group"
  }

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }
}

resource "aws_db_instance" "postgres_db_instance" {
  allocated_storage      = 20
  db_name                = "mydb"
  engine                 = "postgres"
  engine_version         = "14.7"
  instance_class         = "db.t3.medium"
  db_subnet_group_name   = aws_db_subnet_group.postgres_subnet_group.name
  vpc_security_group_ids = [aws_db_security_group.postgres_security_group.id]
  parameter_group_name   = aws_db_parameter_group.postgres_parameter_group.name
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.postgres_kms_key.arn
  multi_az               = true
  final_snapshot_identifier = "pgsnapshot"
  tags = {
    Name = "postgres_db_instance"
  }
}
