  vault_name = aws_glacier_vault.glacier_vault.name
  complete_lock = true
  policy = jsonencode({
    "Version" = "2012-10-17"
    "Statement" = [{
      "Sid" = "VaultLockPolicy"
      "Effect" = "Deny"
      "Principal" = "*"
      "Action" = "s3:DeleteObject"
      "Resource" = "arn:aws:s3:::my-glacier-vault/*"
      "Condition" = {
        "DateGreaterThanEquals" = {
          "aws:GlacierArchiveAgeInDays" = "365"
        }
      }
    }]
  })
}
