  role       = aws_iam_role.db_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSRole"
}

resource "aws_rds_cluster_parameter_group" "db_param_group" {
  name        = "db-param-group"
  family      = "aurora-postgresql14"
  description = "Parameter group for RDS cluster with autoscaling settings"

  parameter {
    name  = "rds.autoscaling.minCapacity"
    value = "2"
    apply_method = "pending-reboot"
  }

  parameter {
    name  = "rds.autoscaling.maxCapacity"
    value = "16"
    apply_method = "pending-reboot"
  }
}

resource "aws_rds_cluster" "db_cluster" {
  cluster_identifier      = "db-cluster"
  engine                  = "aurora-postgresql"
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.db_param_group.name
  engine_version          = "14.6"
  master_username         = "admin"
  master_user_password    = "SecurePassword123!"
  backup_retention_period = 5
  db_subnet_group_name    = "default"
  skip_final_snapshot     = true

  scaling_configuration {
    auto_pause              = true
    max_capacity            = 16
    min_capacity            = 2
    seconds_until_auto_pause = 300
  }
}

resource "aws_rds_cluster_instance" "db_instance" {
  cluster_identifier  = aws_rds_cluster.db_cluster.id
  instance_class      = "db.t3.medium"
  engine              = "aurora-postgresql"
  apply_immediately   = true
}
```

