provider "aws" {
  region = "us-west-2"
}

# Create a default network ACL in the default VPC
resource "aws_network_acl" "default_network_acl" {
  vpc_id = data.aws_vpc.default.id
}

# Fetch the default VPC
data "aws_vpc" "default" {
  default = true
}

# Define an ingress rule allowing all traffic from any source
resource "aws_network_acl_rule" "network_acl_ingress_rule" {
  network_acl_id = aws_network_acl.default_network_acl.id
  rule_number    = 100
  rule_action    = "allow"
  protocol       = "-1" # All protocols
  cidr_block     = "0.0.0.0/0"
  egress         = false
}

# Define an egress rule allowing all traffic to any destination
resource "aws_network_acl_rule" "network_acl_egress_rule" {
  network_acl_id = aws_network_acl.default_network_acl.id
  rule_number    = 100
  rule_action    = "allow"
  protocol       = "-1" # All protocols
  cidr_block     = "0.0.0.0/0"
  egress         = true
}
